"use strict";(self.webpackChunktcmax_docs=self.webpackChunktcmax_docs||[]).push([["8669"],{18386(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>l,frontMatter:()=>a,contentTitle:()=>r,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"usaf-general-use/verifying-issued-items-at-the-end-of-shift","title":"Verifying Issued Items at the End of Shift","description":"At the end of every shift it is common for shops to require that you compare your items out list to empty holes on your shelves to insure everything is accounted for. To do this from TCMax you would need to be logged in and the person logged in would need the \u201Cswitch modes of operation\u201D permission. Once this person is logged in, click on the mode tab up on the top menu bar (the caption will most often be mode=issue/turn in). Click there and switch to End of Shift Inventory Mode. A magenta colored bar will appear across the top of your screen to help remind you that you are in a different mode of operation and you cannot issue or turn in items from this mode. Once you are in End of Shift Inventory Mode simply walk around and scan the holes in your shelves where items are gone (items that are not on the shelf are either missing or issued). Each time you scan something TCMax will say \u201Cremoved\u201D (removing it from the list of issued items).","source":"@site/versioned_docs/version-8.x/usaf-general-use/verifying-issued-items-at-the-end-of-shift.mdx","sourceDirName":"usaf-general-use","slug":"/usaf-general-use/verifying-issued-items-at-the-end-of-shift","permalink":"/tcmax-docs/docs/tcmax/8.x/usaf-general-use/verifying-issued-items-at-the-end-of-shift","draft":false,"unlisted":false,"tags":[],"version":"8.x","sidebarPosition":1,"frontMatter":{"id":"verifying-issued-items-at-the-end-of-shift","sidebar_position":1},"sidebar":"tcmaxSidebar","previous":{"title":"USAF General Use","permalink":"/tcmax-docs/docs/tcmax/8.x/category/usaf-general-use"},"next":{"title":"Generate a TCMax Deployable Database","permalink":"/tcmax-docs/docs/tcmax/8.x/usaf-general-use/generate-a-tcmax-deployable-database"}}'),s=o(74848),i=o(28453);let a={id:"verifying-issued-items-at-the-end-of-shift",sidebar_position:1},r="Verifying Issued Items at the End of Shift",d={},h=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"verifying-issued-items-at-the-end-of-shift",children:"Verifying Issued Items at the End of Shift"})}),"\n",(0,s.jsx)(t.p,{children:"At the end of every shift it is common for shops to require that you compare your items out list to empty holes on your shelves to insure everything is accounted for. To do this from TCMax you would need to be logged in and the person logged in would need the \u201Cswitch modes of operation\u201D permission. Once this person is logged in, click on the mode tab up on the top menu bar (the caption will most often be mode=issue/turn in). Click there and switch to End of Shift Inventory Mode. A magenta colored bar will appear across the top of your screen to help remind you that you are in a different mode of operation and you cannot issue or turn in items from this mode. Once you are in End of Shift Inventory Mode simply walk around and scan the holes in your shelves where items are gone (items that are not on the shelf are either missing or issued). Each time you scan something TCMax will say \u201Cremoved\u201D (removing it from the list of issued items)."}),"\n",(0,s.jsx)(t.p,{children:"When you scan an item in Inventory or Special Inventory modes all you are really doing is putting today\u2019s time/date into the date last inventoried field for that item in your database. If you make a mistake and scan the wrong barcode simply scan it again immediately and TCMax will ask if you want to delete the record of that item having been inventoried. Also keep in mind that Special Inventory mode and Inventory mode will both behave the same way and should serve the same purpose. They are two separate modes of operation to allow you to be able to do more than one inventory in the same place at the same time and keep your results separate. If you have a general login be sure to switch TCMax back in to Mode=Issue/Turn In when you\u2019re done so the next shift doesn\u2019t accidentally inventory something instead of issuing or turning in. If a new person logs into TCMax it will default back to the Issue/Turn In mode unless preferences have been set to override this function."})]})}function l(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,t,o){o.d(t,{R:()=>a,x:()=>r});var n=o(96540);let s={},i=n.createContext(s);function a(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);